<?php
declare(strict_types=1);
require __DIR__ . '/../config/config.php';

$action = $_GET['action'] ?? 'dashboard';

if ($_SERVER['REQUEST_METHOD'] === 'POST' && $action === 'receive_stock') {
    $medicineId=(int)($_POST['medicine_id']??0); $boxes=max(0,(int)($_POST['boxes']??0)); $strips=max(0,(int)($_POST['strips']??0)); $units=max(0,(int)($_POST['units']??0)); $batch=trim($_POST['batch_no']??'');
    if ($batch==='') { http_response_code(422); exit('Batch number is required.'); }
    $m=db()->prepare('SELECT * FROM medicines WHERE id=?'); $m->execute([$medicineId]); $medicine=$m->fetch();
    if (!$medicine) { http_response_code(422); exit('Medicine not found.'); }
    $totalUnits=$boxes*$medicine['strips_per_box']*$medicine['units_per_strip']+$strips*$medicine['units_per_strip']+$units;
    if ($totalUnits<1) { http_response_code(422); exit('Enter at least one box, strip, or tablet.'); }
    $s=db()->prepare('INSERT INTO batches (medicine_id,batch_no,expiry_date,units_received,units_remaining,purchase_unit_cost) VALUES (?,?,?,?,?,?)');
    $s->execute([$medicineId,$batch,$_POST['expiry_date']?:null,$totalUnits,$totalUnits,(float)($_POST['purchase_unit_cost']??0)]);
    $batchId=(int)db()->lastInsertId();
    db()->prepare('INSERT INTO stock_movements (medicine_id,batch_id,movement_type,quantity_units,note) VALUES (?,?,"purchase",?,?)')->execute([$medicineId,$batchId,$totalUnits,'Stock received']);
    header('Location: ?action=inventory&saved=1'); exit;
}

if ($_SERVER['REQUEST_METHOD'] === 'POST' && $action === 'add_medicine') {
    $stmt=db()->prepare('INSERT INTO medicines (name,generic_name,strength,manufacturer,barcode,unit_name,units_per_strip,strips_per_box,purchase_price,retail_unit_price,reorder_level) VALUES (?,?,?,?,?,?,?,?,?,?,?)');
    $stmt->execute([trim($_POST['name']),trim($_POST['generic_name']??''),trim($_POST['strength']??''),trim($_POST['manufacturer']??''),trim($_POST['barcode']??'')?:null,trim($_POST['unit_name']??'tablet'),max(1,(int)$_POST['units_per_strip']),max(1,(int)$_POST['strips_per_box']),max(0,(float)$_POST['purchase_price']),max(0,(float)$_POST['retail_unit_price']),max(0,(int)$_POST['reorder_level'])]);
    header('Location: ?action=medicines&saved=1'); exit;
}

if ($_SERVER['REQUEST_METHOD'] === 'POST' && $action === 'sale') {
    $items=json_decode($_POST['items']??'[]',true)?:[]; if(!$items){http_response_code(422);exit('Cart is empty.');}
    $pdo=db();$pdo->beginTransaction();
    try {
        $subtotal=0;foreach($items as $item)$subtotal+=(float)$item['price']*(int)$item['qty'];
        $discount=max(0,(float)($_POST['discount']??0));$total=max(0,$subtotal-$discount);$paid=max(0,(float)($_POST['paid']??$total));
        $invoice='INV-'.date('YmdHis').'-'.random_int(100,999);
        $pdo->prepare('INSERT INTO sales(invoice_no,subtotal,discount,total,payment_method,paid) VALUES(?,?,?,?,?,?)')->execute([$invoice,$subtotal,$discount,$total,$_POST['payment_method']??'cash',$paid]);$saleId=(int)$pdo->lastInsertId();
        foreach($items as $item){$qty=max(1,(int)$item['qty']);$mid=(int)$item['id'];$b=$pdo->prepare('SELECT * FROM batches WHERE medicine_id=? AND units_remaining>=? ORDER BY expiry_date IS NULL,expiry_date ASC,id ASC FOR UPDATE');$b->execute([$mid,$qty]);$batch=$b->fetch();if(!$batch)throw new RuntimeException('Insufficient stock for '.$item['name']);$line=(float)$item['price']*$qty;$pdo->prepare('INSERT INTO sale_items(sale_id,medicine_id,batch_id,quantity_units,unit_price,line_total) VALUES(?,?,?,?,?,?)')->execute([$saleId,$mid,$batch['id'],$qty,$item['price'],$line]);$pdo->prepare('UPDATE batches SET units_remaining=units_remaining-? WHERE id=?')->execute([$qty,$batch['id']]);$pdo->prepare('INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,reference_id,note) VALUES(?,?,"sale",?,?,?)')->execute([$mid,$batch['id'],-$qty,$saleId,'POS sale']);}
        $pdo->commit();header('Location: ?action=receipt&id='.$saleId);exit;
    }catch(Throwable $e){$pdo->rollBack();http_response_code(400);exit('Sale failed: '.e($e->getMessage()));}
}
function totalStock(int $id):int{$s=db()->prepare('SELECT COALESCE(SUM(units_remaining),0)n FROM batches WHERE medicine_id=?');$s->execute([$id]);return(int)$s->fetch()['n'];}
function head(string $title):void{echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' · '.e(APP_NAME).'</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 '.e(APP_NAME).'</div><nav><a href="?action=dashboard">Dashboard</a><a href="?action=pos">POS</a><a href="?action=medicines">Medicines</a><a href="?action=inventory">Inventory</a><a href="?action=reports">Reports</a></nav></header><main>';}
head(ucfirst($action));
if($action==='dashboard'){$sales=(float)db()->query('SELECT COALESCE(SUM(total),0)n FROM sales WHERE DATE(created_at)=CURDATE()')->fetch()['n'];$count=(int)db()->query('SELECT COUNT(*)n FROM medicines WHERE active=1')->fetch()['n'];$exp=(int)db()->query('SELECT COUNT(*)n FROM batches WHERE expiry_date IS NOT NULL AND expiry_date<=DATE_ADD(CURDATE(),INTERVAL 90 DAY) AND units_remaining>0')->fetch()['n'];?><div class="page-title"><div><div class="eyebrow">PHARMACY MANAGEMENT</div><h1>Good day 👋</h1><p>Run your pharmacy quickly and keep every tablet accounted for.</p></div><a class="btn" href="?action=pos">Open POS</a></div><div class="cards"><div><span>Today's sales</span><b>Rs. <?=money($sales)?></b></div><div><span>Active medicines</span><b><?=$count?></b></div><div><span>Near expiry ≤ 90 days</span><b><?=$exp?></b></div></div><div class="quick-grid"><a href="?action=pos"><strong>⚡ Fast Sale</strong><small>Search or scan a medicine</small></a><a href="?action=inventory"><strong>📦 Receive Stock</strong><small>Add boxes, strips or tablets</small></a><a href="?action=medicines"><strong>💊 Medicines</strong><small>Manage your medicine catalogue</small></a></div>
<?php }elseif($action==='medicines'){$rows=db()->query('SELECT * FROM medicines WHERE active=1 ORDER BY name')->fetchAll();?><div class="page-title"><div><div class="eyebrow">CATALOGUE</div><h1>Medicines</h1><p>Configure the smallest sellable unit for accurate loose-tablet sales.</p></div></div><div class="panel"><h2>Add medicine</h2><form method="post" action="?action=add_medicine" class="grid"><input name="name" placeholder="Brand name *" required><input name="generic_name" placeholder="Generic name"><input name="strength" placeholder="Strength e.g. 500mg"><input name="manufacturer" placeholder="Manufacturer"><input name="barcode" placeholder="Barcode"><input name="unit_name" value="tablet" placeholder="Smallest unit"><input type="number" name="units_per_strip" value="10" min="1" placeholder="Units/strip"><input type="number" name="strips_per_box" value="10" min="1" placeholder="Strips/box"><input type="number" step="0.01" name="purchase_price" placeholder="Purchase price/unit"><input type="number" step="0.01" name="retail_unit_price" placeholder="Retail price/unit *" required><input type="number" name="reorder_level" value="20" min="0" placeholder="Reorder level"><button class="btn">Save medicine</button></form></div><div class="panel"><table><tr><th>Medicine</th><th>Pack</th><th>Retail/unit</th><th>Stock</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['generic_name'])?> <?=e($r['strength'])?></small></td><td><?=$r['units_per_strip']?>/strip × <?=$r['strips_per_box']?> strips/box</td><td>Rs. <?=money((float)$r['retail_unit_price'])?></td><td><?=totalStock((int)$r['id'])?> units</td></tr><?php endforeach;?></table></div>
<?php }elseif($action==='inventory'){$rows=db()->query('SELECT m.*,COALESCE(SUM(b.units_remaining),0)stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id GROUP BY m.id ORDER BY m.name')->fetchAll();$meds=db()->query('SELECT id,name,units_per_strip,strips_per_box FROM medicines WHERE active=1 ORDER BY name')->fetchAll();?><div class="page-title"><div><div class="eyebrow">STOCK CONTROL</div><h1>Inventory</h1><p><b>Batch number is required.</b> Expiry date is optional.</p></div></div><div class="panel"><h2>Receive stock</h2><form method="post" action="?action=receive_stock" class="grid"><select name="medicine_id" required><option value="">Select medicine *</option><?php foreach($meds as $m):?><option value="<?=$m['id']?>"><?=e($m['name'])?> · <?=$m['units_per_strip']?>/strip · <?=$m['strips_per_box']?> strips/box</option><?php endforeach;?></select><label>Batch Number *<input name="batch_no" placeholder="Enter batch number" required></label><label>Expiry Date <span class="optional">(optional)</span><input type="date" name="expiry_date"></label><label>Boxes<input type="number" name="boxes" min="0" value="0"></label><label>Strips<input type="number" name="strips" min="0" value="0"></label><label>Tablets<input type="number" name="units" min="0" value="0"></label><label>Cost / smallest unit<input type="number" step="0.0001" name="purchase_unit_cost" min="0" value="0"></label><button class="btn">Receive stock</button></form></div><div class="panel"><table><tr><th>Medicine</th><th>Stock</th><th>Reorder</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><b><?=$r['stock']?></b> units</td><td><?=$r['reorder_level']?></td></tr><?php endforeach;?></table></div>
<?php }elseif($action==='pos'){$meds=db()->query('SELECT m.*,COALESCE(SUM(b.units_remaining),0)stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id WHERE m.active=1 GROUP BY m.id ORDER BY m.name')->fetchAll();?><div class="page-title"><div><div class="eyebrow">POINT OF SALE</div><h1>Fast Sale</h1><p>Search or scan a medicine, then complete the sale.</p></div></div><div class="pos"><div class="panel"><input id="search" placeholder="🔎 Search medicine or scan barcode" autofocus><div id="results"></div></div><div class="panel cart-panel"><div class="cart-head"><h2>Current Sale</h2><span id="count">0 units</span></div><div id="cart"></div><div class="totals"><div>Subtotal <b>Rs. <span id="subtotal">0.00</span></b></div><label>Discount <input id="discount" type="number" value="0" min="0" step="0.01"></label><div class="grand">Total <strong>Rs. <span id="total">0.00</span></strong></div></div><select id="payment"><option value="cash">Cash</option><option value="card">Card</option><option value="credit">Credit</option></select><input id="paid" type="number" min="0" step="0.01" placeholder="Amount received"><button class="btn checkout" onclick="checkout()">Complete Sale →</button></div></div><script>const medicines=<?=json_encode($meds)?>;let cart=[];const fmt=n=>Number(n).toFixed(2);function renderResults(){let q=document.getElementById('search').value.toLowerCase().trim();let rs=medicines.filter(m=>(m.name+' '+(m.generic_name||'')+' '+(m.barcode||'')).toLowerCase().includes(q)).slice(0,12);document.getElementById('results').innerHTML=rs.map(m=>`<button class="result" onclick="add(${m.id})"><span><b>${m.name}</b><small>${m.generic_name||''} ${m.strength||''} · stock ${m.stock}</small></span><strong>Rs. ${fmt(m.retail_unit_price)} / ${m.unit_name}</strong></button>`).join('')}function add(id){let m=medicines.find(x=>x.id==id);if(!m||m.stock<1)return;let x=cart.find(x=>x.id==id);if(x){if(x.qty>=m.stock)return;x.qty++}else cart.push({id:m.id,name:m.name,price:Number(m.retail_unit_price),qty:1,max:Number(m.stock)});renderCart()}function renderCart(){document.getElementById('cart').innerHTML=cart.length?cart.map((x,i)=>`<div class="cartrow"><span><b>${x.name}</b><small>Rs. ${fmt(x.price)} / unit</small></span><input type="number" min="1" max="${x.max}" value="${x.qty}" onchange="qty(${i},this.value)"><b>Rs. ${fmt(x.price*x.qty)}</b><button onclick="cart.splice(${i},1);renderCart()">×</button></div>`).join(''):'<div class="empty">Your cart is empty.<br><small>Search or scan a medicine to begin.</small></div>';let s=cart.reduce((a,x)=>a+x.price*x.qty,0),d=Number(document.getElementById('discount').value)||0;document.getElementById('count').textContent=cart.reduce((a,x)=>a+x.qty,0)+' units';document.getElementById('subtotal').textContent=fmt(s);document.getElementById('total').textContent=fmt(Math.max(0,s-d))}function qty(i,v){cart[i].qty=Math.max(1,Math.min(cart[i].max,parseInt(v)||1));renderCart()}function checkout(){if(!cart.length)return alert('Cart is empty');let d=Number(document.getElementById('discount').value)||0,s=cart.reduce((a,x)=>a+x.price*x.qty,0),t=Math.max(0,s-d),paid=Number(document.getElementById('paid').value)||t;let f=document.createElement('form');f.method='post';f.action='?action=sale';[['items',JSON.stringify(cart)],['discount',d],['payment_method',document.getElementById('payment').value],['paid',paid]].forEach(([n,v])=>{let i=document.createElement('input');i.type='hidden';i.name=n;i.value=v;f.appendChild(i)});document.body.appendChild(f);f.submit()}document.getElementById('search').addEventListener('input',renderResults);document.getElementById('search').addEventListener('keydown',e=>{if(e.key==='Enter'){let b=document.querySelector('.result');if(b)b.click()}});document.getElementById('discount').addEventListener('input',renderCart);renderResults();renderCart();</script>
<?php }elseif($action==='receipt'){$s=db()->prepare('SELECT * FROM sales WHERE id=?');$s->execute([(int)$_GET['id']]);$sale=$s->fetch();$i=db()->prepare('SELECT si.*,m.name FROM sale_items si JOIN medicines m ON m.id=si.medicine_id WHERE sale_id=?');$i->execute([$sale['id']]);$items=$i->fetchAll();?><div class="receipt panel"><div class="eyebrow">SALE COMPLETE</div><h1><?=e(APP_NAME)?></h1><p>Invoice: <?=e($sale['invoice_no'])?></p><?php foreach($items as $x):?><div class="cartrow"><span><?=e($x['name'])?> × <?=$x['quantity_units']?></span><b>Rs. <?=money((float)$x['line_total'])?></b></div><?php endforeach;?><hr><p>Subtotal: Rs. <?=money((float)$sale['subtotal'])?></p><p>Discount: Rs. <?=money((float)$sale['discount'])?></p><h2>Total: Rs. <?=money((float)$sale['total'])?></h2><button class="btn" onclick="window.print()">Print Receipt</button> <a class="btn secondary" href="?action=pos">New Sale</a></div>
<?php }elseif($action==='reports'){$top=db()->query('SELECT m.name,SUM(si.quantity_units)units,SUM(si.line_total)sales FROM sale_items si JOIN medicines m ON m.id=si.medicine_id GROUP BY m.id ORDER BY units DESC LIMIT 20')->fetchAll();?><div class="page-title"><div><div class="eyebrow">REPORTING</div><h1>Sales Report</h1><p>Top medicines by units sold.</p></div></div><div class="panel"><table><tr><th>Medicine</th><th>Units sold</th><th>Sales</th></tr><?php foreach($top as $r):?><tr><td><?=e($r['name'])?></td><td><?=$r['units']?></td><td>Rs. <?=money((float)$r['sales'])?></td></tr><?php endforeach;?></table></div><?php }else{echo '<div class="panel"><h1>Page not found</h1><a class="btn" href="?action=dashboard">Dashboard</a></div>';}
?>
</main></body></html>
